def weighted_pick(case):
    items = list(case.get('items') or [])
    if not items:
        raise ValueError('В кейсе нет предметов')
    total = sum(max(0.0, float(x.get('chance', 0))) for x in items)
    if total <= 0:
        return items[0]
    import secrets
    roll = secrets.randbelow(10_000_000) / 10_000_000 * total
    acc = 0.0
    for item in items:
        acc += max(0.0, float(item.get('chance', 0)))
        if roll < acc:
            return item
    return items[-1]
